if(config.error||parsed.errors.length)throw Error('Invalid resolver configuration');
const controls=['./index','./index.js','./index.ts','.'].map(specifier=>{
 const result=ts.resolveModuleName(specifier,resolve('tests/integration/concurrent-commands.test.ts'),parsed.options,ts.sys).resolvedModule;
 const destination=result?resolve(result.resolvedFileName):'';
 if(destination.toLowerCase()!==target.toLowerCase())throw Error('Positive import control failed '+specifier);
