assert(packet.removed.path===target&&!existsSync(target),'Target not removed');
assert(sourceHash(execFileSync('git',['show',packet.base_revision+':'+target],{encoding:'utf8'}))===packet.removed.sourceHash,'Recovery content mismatch');
for(const input of [...packet.after.sourceInputs,...packet.controls.sourceInputs])assert(hash(input.path)===input.sourceHash,'Stale source '+input.path);
assert(JSON.stringify(packet.before.sourceInputs.filter((x:any)=>x.path!==target))===JSON.stringify(packet.after.sourceInputs),'Non-target source changed');
const before=read('.git/b11-integration-before.json'), after=read('.git/b11-integration-after.json');
assert(sourceHash(JSON.stringify(before.imports))===packet.before.importGraphHash&&sourceHash(JSON.stringify(after.imports))===packet.after.importGraphHash,'Raw graph mismatch');
assert(JSON.stringify(before.imports.filter((x:any)=>x.path!==target))===JSON.stringify(after.imports),'Remaining graph changed');
assert(!packet.before.reverseImports.length&&!packet.after.reverseImports.length&&packet.controls.controls.length===4&&packet.controls.controls.every((x:any)=>x.matched),'Missing negative/positive reference proof');
