const live=discoverInventory(process.cwd()), catalog=read(root+'executable-catalog.json'), manifest=read(root+'quality-classifications.json');
assert(live.files.length===447&&JSON.stringify(live)===JSON.stringify(catalog)&&!validateInventory(live,manifest).length,'Catalog mismatch');
assert(manifest.retiredFiles.filter((x:any)=>x.path===target).length===1&&manifest.retiredFiles.find((x:any)=>x.path===target).sourceHash===packet.removed.sourceHash,'Missing retirement record');
